"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[94422],{3331:(e,a,o)=>{o.d(a,{R:()=>n,x:()=>t});var s=o(36672);const i={},r=s.createContext(i);function n(e){const a=s.useContext(r);return s.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:n(e.components),s.createElement(r.Provider,{value:a},e.children)}},28789:(e,a,o)=>{o.r(a),o.d(a,{assets:()=>l,contentTitle:()=>t,default:()=>u,frontMatter:()=>n,metadata:()=>s,toc:()=>d});const s=JSON.parse('{"id":"2023/04/17","title":"2023-04-17","description":"De-Stressing Booking.com","source":"@site/i18n/es/docusaurus-plugin-content-docs/current/2023/04/17.md","sourceDirName":"2023/04","slug":"/2023/04/17","permalink":"/es/2023/04/17","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/es/docusaurus-plugin-content-docs//current/2023/04/17.md","tags":[],"version":"current","frontMatter":{"localized_date":"17 de abril de 2023","top_news":"De-Stressing Booking.com"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-18","permalink":"/es/2023/04/18"},"next":{"title":"2023-04-16","permalink":"/es/2023/04/16"}}');var i=o(23420),r=o(3331);const n={localized_date:"17 de abril de 2023",top_news:"De-Stressing Booking.com"},t="2023-04-17",l={},d=[{value:"De-Stressing Booking.com",id:"de-stressing-bookingcom",level:2},{value:"He utilizado Stable Diffusion y Dreambooth para crear un retrato art\xedstico de mi perro.",id:"he-utilizado-stable-diffusion-y-dreambooth-para-crear-un-retrato-art\xedstico-de-mi-perro",level:2},{value:"AT&amp;T Wireless parece estar inutilizando algunos sitios web.",id:"att-wireless-parece-estar-inutilizando-algunos-sitios-web",level:2},{value:"Future Blues - P\xe1gina de Emily sobre Cowboy Bebop (1999)",id:"future-blues---p\xe1gina-de-emily-sobre-cowboy-bebop-1999",level:2},{value:"Lavavajillas Salm\xf3n",id:"lavavajillas-salm\xf3n",level:2},{value:"Pico3D: Motor de juegos 3D de mundo abierto para el PicoSystem (microcontrolador RP2040)",id:"pico3d-motor-de-juegos-3d-de-mundo-abierto-para-el-picosystem-microcontrolador-rp2040",level:2},{value:"Wayback: Servicio de archivo autoalojado integrado con Internet Archive",id:"wayback-servicio-de-archivo-autoalojado-integrado-con-internet-archive",level:2},{value:"La biblioteca de composici\xf3n matem\xe1tica m\xe1s r\xe1pida para la web",id:"la-biblioteca-de-composici\xf3n-matem\xe1tica-m\xe1s-r\xe1pida-para-la-web",level:2},{value:"&#39;Algebra for none&#39; fracasa en San Francisco",id:"algebra-for-none-fracasa-en-san-francisco",level:2},{value:"FSF arremete contra Google por eliminar JPEG-XL en Chrome",id:"fsf-arremete-contra-google-por-eliminar-jpeg-xl-en-chrome",level:2}];function c(e){const a={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.header,{children:(0,i.jsx)(a.h1,{id:"2023-04-17",children:"2023-04-17"})}),"\n",(0,i.jsx)(a.h2,{id:"de-stressing-bookingcom",children:"De-Stressing Booking.com"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://www.alexcharlton.co/projects/booking-com-de-stresser",children:"Original"}),'.\nEl autor comparte un art\xedculo de opini\xf3n sobre el uso excesivo de t\xe1cticas de persuasi\xf3n en sitios web de comercio electr\xf3nico, en concreto Booking.com, y presenta su extensi\xf3n de Chrome, "De-stresser", que elimina los mensajes y notificaciones de Booking.com que provocan estr\xe9s, ofreciendo a los usuarios una experiencia m\xe1s agradable. Al ocultar las etiquetas de persuasi\xf3n y ajustar el lenguaje para que suene m\xe1s positivo, el De-stresser permite una experiencia de reserva m\xe1s tranquila y relajada para los usuarios. La extensi\xf3n ya est\xe1 disponible en Booking.com.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35590734",children:"Discussion Service"}),'.\nBooking.com se enfrenta a cr\xedticas por su uso de t\xe1cticas de venta de alta presi\xf3n, incluidos mensajes de urgencia y ventanas emergentes que pueden disuadir a los usuarios. Los cr\xedticos sostienen que este enfoque da prioridad a las m\xe9tricas a corto plazo sobre la lealtad del cliente a largo plazo. Los usuarios afirman haber encontrado formas de evitar estas t\xe1cticas, como el uso de extensiones para bloquearlas o filtrarlas. Mientras tanto, los usuarios de Discussion Service debaten sobre las ventajas de las pruebas A/B, y algunos se\xf1alan su potencial para crear "patrones oscuros" en los sitios web. A pesar de estas preocupaciones, muchos usuarios siguen utilizando agregadores de reservas como Booking.com y Expedia, ya sea por comodidad o porque ofrecen precios y pol\xedticas de cancelaci\xf3n favorables. Algunos expertos advierten de que reservar directamente con los hoteles puede ofrecer mejores opciones de resoluci\xf3n de conflictos, mientras que otros se\xf1alan que las comisiones de los sitios de reservas pueden variar mucho seg\xfan el hotel. No obstante, los programas de fidelidad de los hoteles pueden ofrecer importantes ventajas a los viajeros frecuentes.']}),"\n",(0,i.jsx)(a.h2,{id:"he-utilizado-stable-diffusion-y-dreambooth-para-crear-un-retrato-art\xedstico-de-mi-perro",children:"He utilizado Stable Diffusion y Dreambooth para crear un retrato art\xedstico de mi perro."}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://www.shruggingface.com/blog/how-i-used-stable-diffusion-and-dreambooth-to-create-a-painted-portrait-of-my-dog",children:"Original"}),".\nEl art\xedculo analiza el uso de t\xe9cnicas de difusi\xf3n estable y Dreambooth AI para crear un retrato pintado de alta calidad de un perro. El autor comparte todo su flujo de trabajo y proporciona instrucciones detalladas sobre c\xf3mo entrenar un modelo Dreambooth en fotos de su perro. El art\xedculo tambi\xe9n analiza el uso del escalado para ampliar im\xe1genes peque\xf1as para impresiones de alta calidad y presenta la difusi\xf3n estable como un cambio de juego para el mundo del arte generativo de texto a imagen."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35592847",children:"Discussion Service"}),".\nUn usuario de Discussion Service utiliz\xf3 Stable Diffusion y Dreambooth para crear un retrato art\xedstico de su perro, mientras que en los comentarios se discut\xeda la oposici\xf3n al arte generado por IA y los debates en torno a los derechos de autor y el uso justo. El uso de IA generativa para el arte plantea cuestiones \xe9ticas en relaci\xf3n con la ley de derechos de autor y el uso justo, con opiniones divididas al respecto. Algunos criticaron a Stable Diffusion por utilizar obras de arte robadas sin compensaci\xf3n como datos de entrenamiento, mientras que otros alabaron la tecnolog\xeda y su potencial para seguir innovando en este campo."]}),"\n",(0,i.jsx)(a.h2,{id:"att-wireless-parece-estar-inutilizando-algunos-sitios-web",children:"AT&T Wireless parece estar inutilizando algunos sitios web."}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://adriano.fyi/post/2023/2023-04-16-att-traffic-shaping-makes-websites-unusable/",children:"Original"}),'.\nEl plan "ilimitado" de 100Mbit de AT&T con 50GB para datos priorizados podr\xeda moldear el tr\xe1fico de forma agresiva, provocando que algunos sitios web sean inutilizables, mientras que una prueba demostr\xf3 que una tarjeta SIM de Verizon no ten\xeda el mismo problema. El tr\xe1fico de Akamai muestra indicios de manipulaci\xf3n intencionada del flujo TCP. El moldeado del tr\xe1fico afecta s\xf3lo a las cuentas de s\xf3lo datos de las cuentas empresariales.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35592607",children:"Discussion Service"}),".\nAl parecer, AT&T Wireless est\xe1 estrangulando las direcciones IP de algunos sitios de streaming de v\xeddeo, lo que hace inutilizables algunos sitios web y provoca discrepancias en las pruebas de velocidad de Internet. Los usuarios han sugerido soluciones como presentar una queja a la FCC, utilizar una VPN para evitar la limitaci\xf3n o probar con una APN diferente. Algunos comentaristas se muestran esc\xe9pticos sobre las nefastas intenciones que se esconden tras el estrangulamiento, mientras que otros proponen soluciones como limitar la velocidad o rebajar la calidad del v\xeddeo para preservar la asignaci\xf3n de datos."]}),"\n",(0,i.jsx)(a.h2,{id:"future-blues---p\xe1gina-de-emily-sobre-cowboy-bebop-1999",children:"Future Blues - P\xe1gina de Emily sobre Cowboy Bebop (1999)"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://futureblues.com/",children:"Original"}),".\nLo siento, no hay ning\xfan texto que pueda resumir."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35589124",children:"Discussion Service"}),".\nLos usuarios de Discussion Service expresan su nostalgia por los dise\xf1os originales y creativos de los sitios web cl\xe1sicos, contrast\xe1ndolos con la naturaleza estandarizada, ruidosa y monetizada de los sitios web modernos, lo que sugiere un anhelo de paisajes medi\xe1ticos m\xe1s art\xedsticos y centrados en la individualidad. Surgen puntos de debate comparando Wikipedia y Fandom, y la distinci\xf3n entre sitios s\xf3lo para m\xf3viles y s\xf3lo para ordenadores de sobremesa, y el dise\xf1o del sitio web inspira tanto nostalgia como asombro por su longevidad. En conjunto, el art\xedculo ofrece una visi\xf3n de los recuerdos de los usuarios de los primeros tiempos de Internet y sirve de plataforma para debatir el estado actual de la Red."]}),"\n",(0,i.jsx)(a.h2,{id:"lavavajillas-salm\xf3n",children:"Lavavajillas Salm\xf3n"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://en.wikipedia.org/wiki/Dishwasher_salmon",children:"Original"}),".\nEl salm\xf3n del lavavajillas es un plato de pescado que se prepara envolviendo trozos de salm\xf3n en al menos dos capas de papel de aluminio y meti\xe9ndolos en el lavavajillas durante el ciclo de lavado y secado. El m\xe9todo fue demostrado por primera vez en EE.UU. por Vincent Price en 1975 y desde entonces ha aparecido en varios medios de comunicaci\xf3n. Sin embargo, existe preocupaci\xf3n por la consistencia de las temperaturas en los lavavajillas, que puede dar lugar a una cocci\xf3n incompleta y a posibles riesgos para la salud."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35586683",children:"Discussion Service"}),".\nUn art\xedculo de Hacker News sobre la cocci\xf3n de salm\xf3n en el lavavajillas suscita un debate sobre la seguridad de este m\xe9todo de cocci\xf3n, en el que usuarios del sector de la seguridad alimentaria rebaten las afirmaciones hechas en la investigaci\xf3n de un YouTuber. Aunque la seguridad de la cocci\xf3n en lavavajillas depende de m\xfaltiples factores, se requieren al menos 63\xb0C durante 15 segundos para matar las bacterias del salm\xf3n."]}),"\n",(0,i.jsx)(a.h2,{id:"pico3d-motor-de-juegos-3d-de-mundo-abierto-para-el-picosystem-microcontrolador-rp2040",children:"Pico3D: Motor de juegos 3D de mundo abierto para el PicoSystem (microcontrolador RP2040)"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://github.com/bernhardstrobl/Pico3D",children:"Original"}),".\nEl motor de juegos Pico3D utiliza el segundo n\xfacleo del RP2040 como rasterizador/GPU dedicado para ejecutar un juego completo en 3D de mundo abierto en un microcontrolador de 1 d\xf3lar. El motor contiene una peque\xf1a ciudad y sus afueras con zombis a los que se puede disparar, y dispone de tutoriales de Blender para crear mundos de juego. La simulaci\xf3n del motor actualmente incluye 50 NPCs y 50 zombies al mismo tiempo, con renderizado optimizado con distancia y view frustum culling."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35589172",children:"Discussion Service"}),".\nSe ha desarrollado un nuevo motor de juegos 3D llamado Pico3D para el microcontrolador RP2040 con una pantalla de 120x120px, y carece de suficiente memoria y RAM de v\xeddeo, pero tiene una API unificada. Los hackers est\xe1n entusiasmados con las formas creativas de utilizar el Pico/RP2040, y la aplicaci\xf3n \xfanica de chips de RAM en el b\xfafer de fotogramas hace que este art\xedculo destaque en el sitio de tecnolog\xeda."]}),"\n",(0,i.jsx)(a.h2,{id:"wayback-servicio-de-archivo-autoalojado-integrado-con-internet-archive",children:"Wayback: Servicio de archivo autoalojado integrado con Internet Archive"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://github.com/wabarc/wayback",children:"Original"}),".\nWayback es una herramienta de archivo autoalojada cuyo objetivo es instantanear p\xe1ginas web en c\xe1psulas de tiempo. Es gratuita, de c\xf3digo abierto, multiplataforma y permite una integraci\xf3n m\xe1s sencilla con diversas plataformas, como Internet Archive, archive.today, IPFS y Telegraph. Tambi\xe9n ofrece varias opciones de instalaci\xf3n, como GitHub, Snapcraft, APT, RPM y Homebrew."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35586845",children:"Discussion Service"}),'.\nEl servicio de archivado autoalojado Wabarc hace instant\xe1neas de p\xe1ginas web en "c\xe1psulas del tiempo" y almacena archivos para su uso sin conexi\xf3n; sin embargo, los usuarios de Discussion Service critican la falta de claridad del README y de documentaci\xf3n. Otros proyectos similares son ArchiveBox, Shiori, DiskerNet y SingleFile; HTTrack Website Copier se recomienda para descargar un sitio web completo localmente, mientras que Browsertrix/Brozzler rastrea con navegadores sin cabeza para mayor precisi\xf3n. Un usuario de Discussion Service recomienda The Old Net para navegar con navegadores antiguos/modernos sin JS, y el repo enlazado necesita m\xe1s claridad sobre la compartibilidad y los est\xe1ndares de archivo establecidos.']}),"\n",(0,i.jsx)(a.h2,{id:"la-biblioteca-de-composici\xf3n-matem\xe1tica-m\xe1s-r\xe1pida-para-la-web",children:"La biblioteca de composici\xf3n matem\xe1tica m\xe1s r\xe1pida para la web"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://katex.org/",children:"Original"}),".\nKaTeX es una biblioteca de composici\xf3n matem\xe1tica r\xe1pida para la web que ofrece un dise\xf1o de calidad de impresi\xf3n basado en TeX de Donald Knuth, no tiene dependencias, y se puede combinar f\xe1cilmente con los recursos del sitio web para la representaci\xf3n del lado del servidor utilizando Node.js. Su sencilla API renderiza eficientemente expresiones matem\xe1ticas, incluso en p\xe1ginas con m\xfaltiples expresiones, sin limitaciones de navegador o entorno, y es de c\xf3digo abierto bajo la Licencia MIT."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35588985",children:"Discussion Service"}),".\nKaTeX, la biblioteca de composici\xf3n matem\xe1tica m\xe1s r\xe1pida para la web, carece de soporte para diagramas, lo que la hace inadecuada para algunos matem\xe1ticos, mientras que MathJax y AsciiMath tienen proyectos similares. Se ha compartido un sitio web comparativo, y los usuarios de Hacker News debaten sobre el rendimiento y la viabilidad de adaptar el marcado a diferentes contextos."]}),"\n",(0,i.jsx)(a.h2,{id:"algebra-for-none-fracasa-en-san-francisco",children:"'Algebra for none' fracasa en San Francisco"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://www.joannejacobs.com/post/algebra-for-none-fails-in-san-francisco",children:"Original"}),'.\nLa pol\xedtica de "\xc1lgebra para ninguno" del distrito escolar unificado de San Francisco no consigui\xf3 mejorar el rendimiento de los estudiantes negros e hispanos en matem\xe1ticas avanzadas, seg\xfan un estudio realizado por profesores de Stanford, lo que provoc\xf3 un aumento de la brecha de rendimiento. La decisi\xf3n de retrasar el \xe1lgebra hasta el noveno curso y colocar a los alumnos de bajo y alto rendimiento en las mismas clases no ayud\xf3 a los estudiantes de bajo rendimiento y dificult\xf3 el \xe9xito de los de alto rendimiento. Las familias que pueden permit\xedrselo han recurrido a cursos en l\xednea o a escuelas privadas. Un grupo de padres ha presentado una demanda contra el distrito, alegando que viola la ley estatal sobre el acceso equitativo a las matem\xe1ticas avanzadas.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35595026",children:"Discussion Service"}),".\nLa pol\xedtica de San Francisco de retrasar el \xe1lgebra hasta 9\xba curso y colocar a los alumnos de bajo, medio y alto rendimiento en las mismas clases ha sido criticada, y algunos sugieren que los conceptos matem\xe1ticos fundamentales deber\xedan ense\xf1arse antes. Algunos usuarios de Discussion Service sugieren incentivar el \xe9xito acad\xe9mico y extraescolar vincul\xe1ndolo a una recompensa econ\xf3mica, mientras que otros sostienen que subvencionar la educaci\xf3n superior mediante sistemas de cr\xe9ditos para pagar la universidad m\xe1s tarde ser\xeda una soluci\xf3n mejor. Hay debates sobre la utilidad de la educaci\xf3n matem\xe1tica tradicional y la eficacia de aumentar la financiaci\xf3n para reducir el tama\xf1o de las clases, y algunos usuarios sugieren ense\xf1ar matem\xe1ticas a trav\xe9s de problemas de ingenier\xeda y las ventajas de la educaci\xf3n en l\xednea."]}),"\n",(0,i.jsx)(a.h2,{id:"fsf-arremete-contra-google-por-eliminar-jpeg-xl-en-chrome",children:"FSF arremete contra Google por eliminar JPEG-XL en Chrome"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"https://www.phoronix.com/news/FSF-Slams-Google-JPEG-XL",children:"Original"}),'.\nLa Free Software Foundation critica la decisi\xf3n de Google de eliminar la compatibilidad con JPEG-XL en Chrome y subraya la necesidad de elegir navegador y formatos multimedia libres. A pesar del clamor de la comunidad, los ingenieros de Google siguieron adelante con la decisi\xf3n, que sigue siendo uno de los asuntos "estrella" en la historia del proyecto Chromium. Los usuarios han mostrado su firme apoyo a JPEG-XL, pero parece prevalecer el inter\xe9s de Google por el control frente a la libertad.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35589179",children:"Discussion Service"}),".\nGoogle se enfrenta a las cr\xedticas de la Free Software Foundation por dejar de soportar JPEG-XL en Chrome a pesar de su adopci\xf3n por los principales editores de im\xe1genes. Algunos usuarios argumentan que formatos m\xe1s antiguos como PNG y JPEG son suficientes, mientras que otros prefieren c\xf3decs como AVIF para v\xeddeo. El debate se centra en la viabilidad y la adopci\xf3n de nuevos formatos de imagen en el ecosistema, con el apoyo de la industria y el inter\xe9s en JPEG-XL, pero la adopci\xf3n depende de que todos los principales navegadores lo soporten."]})]})}function u(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,i.jsx)(a,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}}}]);